function validateCompletionResponse(payload: any): { valid: boolean; text?: string; totalTokens?: number; error?: string } {
  if (!payload || typeof payload !== 'object') {
    return { valid: false, error: 'Payload must be a non-null object' };
  }
  if (typeof payload.id !== 'string') {
    return { valid: false, error: 'Field id is required and must be string' };
  }
  if (!Array.isArray(payload.choices) || payload.choices.length === 0) {
    return { valid: false, error: 'Choices must be a non-empty array' };
  }
  const first = payload.choices[0];
  if (!first || typeof first !== 'object' || !first.message || typeof first.message.content !== 'string') {
    return { valid: false, error: 'Choice missing message.content string' };
  }
  const totalTokens = payload.usage && typeof payload.usage.total_tokens === 'number' ? payload.usage.total_tokens : undefined;
  return { valid: true, text: first.message.content, totalTokens };
}

