  const totalReserved = systemPromptTokens + historyTokens + maxOutputTokens;
  const availableForUser = Math.max(0, contextWindowSize - totalReserved);
  const willFit = contextWindowSize >= totalReserved;
  return { availableForUser, willFit, totalReserved };
}

