function vectorNormAndDotProduct(vecA: number[], vecB: number[]): { dotProduct: number; normA: number; normB: number } {
  if (vecA.length !== vecB.length || vecA.length === 0) {
    return { dotProduct: 0, normA: 0, normB: 0 };
  }
  let dot = 0;
  let sumA = 0;
  let sumB = 0;
  for (let i = 0; i < vecA.length; i++) {
    dot += vecA[i] * vecB[i];
    sumA += vecA[i] * vecA[i];
    sumB += vecB[i] * vecB[i];
  }
  const normA = Math.round(Math.sqrt(sumA) * 10000) / 10000;
  const normB = Math.round(Math.sqrt(sumB) * 10000) / 10000;
  return { dotProduct: Math.round(dot * 10000) / 10000, normA, normB };
}

aideploy-web-assign-day-8:
function computeCosineSimilarity(vecA: number[], vecB: number[]): number {
  if (vecA.length !== vecB.length || vecA.length === 0) return 0;
  let dot = 0;
  let sumA = 0;
  let sumB = 0;
  for (let i = 0; i < vecA.length; i++) {
    dot += vecA[i] * vecB[i];
    sumA += vecA[i] * vecA[i];
    sumB += vecB[i] * vecB[i];
  }
  if (sumA === 0 || sumB === 0) return 0;
  const sim = dot / (Math.sqrt(sumA) * Math.sqrt(sumB));
  return Math.round(sim * 10000) / 10000;
}

