class SemanticVectorCache {
  private items: { key: string; embedding: number[]; response: string }[] = [];
  set(key: string, embedding: number[], response: string): void {
    this.items.push({ key, embedding, response });
  }
  findClosest(queryEmbedding: number[], minSimilarity: number): { hit: boolean; key?: string; response?: string; similarity?: number } {
    let bestSim = -1;
    let bestItem: { key: string; embedding: number[]; response: string } | null = null;
    for (const item of this.items) {
      const sim = this.cosineSim(item.embedding, queryEmbedding);
      if (sim > bestSim) {
        bestSim = sim;
        bestItem = item;
      }
    }
    if (bestItem && bestSim >= minSimilarity) {
      return { hit: true, key: bestItem.key, response: bestItem.response, similarity: Math.round(bestSim * 10000) / 10000 };
    }
    return { hit: false };
  }
  private cosineSim(a: number[], b: number[]): number {
    if (a.length !== b.length || a.length === 0) return 0;
    let dot = 0, sa = 0, sb = 0;
    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      sa += a[i] * a[i];
      sb += b[i] * b[i];
    }
    if (sa === 0 || sb === 0) return 0;
    return dot / (Math.sqrt(sa) * Math.sqrt(sb));
  }
}

