class TokenBucketRateLimiter {
  private currentTokens: number;
  private lastRefillMs: number = 0;
  constructor(public maxCapacity: number, public refillRatePerSec: number) {
    this.currentTokens = maxCapacity;
  }
  tryConsume(tokens: number, nowMs: number): { allowed: boolean; remainingTokens: number } {
    if (this.lastRefillMs === 0) {
      this.lastRefillMs = nowMs;
    } else {
      const elapsedSec = (nowMs - this.lastRefillMs) / 1000;
      const refilled = elapsedSec * this.refillRatePerSec;
      this.currentTokens = Math.min(this.maxCapacity, this.currentTokens + refilled);
      this.lastRefillMs = nowMs;
    }
    if (this.currentTokens >= tokens) {
      this.currentTokens -= tokens;
      return { allowed: true, remainingTokens: Math.floor(this.currentTokens) };
    }
    return { allowed: false, remainingTokens: Math.floor(this.currentTokens) };
  }
}

