class SlidingWindowUserLimiter {
  private userTimestamps = new Map<string, number[]>();
  constructor(public windowMs: number, public maxRequests: number) {}
  recordRequest(userId: string, timestampMs: number): { allowed: boolean; currentCount: number; resetInMs: number } {
    const history = this.userTimestamps.get(userId) || [];
    const cutoff = timestampMs - this.windowMs;
    const valid = history.filter(t => t > cutoff);
    if (valid.length < this.maxRequests) {
      valid.push(timestampMs);
      this.userTimestamps.set(userId, valid);
      return { allowed: true, currentCount: valid.length, resetInMs: this.windowMs };
    }
    const oldest = valid[0];
    const resetInMs = Math.max(0, oldest + this.windowMs - timestampMs);
    return { allowed: false, currentCount: valid.length, resetInMs };
  }
}

