function scorePromptComplexity(prompt: string): { score: number; recommendedTier: 'small' | 'medium' | 'frontier'; reasons: string[] } {
  let score = 0;
  const reasons: string[] = [];
  if (prompt.length > 2000) {
    score += 50;
    reasons.push('HIGH_TOKEN_LENGTH');
  } else if (prompt.length > 500) {
    score += 20;
    reasons.push('MEDIUM_TOKEN_LENGTH');
  }
  if (prompt.includes('```')) {
    score += 25;
    reasons.push('CONTAINS_CODE_BLOCK');
  }
  const lower = prompt.toLowerCase();
  if (lower.includes('step by step') || lower.includes('prove') || lower.includes('mathematical proof') || lower.includes('architect')) {
    score += 25;
    reasons.push('DEEP_REASONING_REQUIRED');
  }
  if (lower.includes('json schema') || lower.includes('strict json')) {
    score += 15;
    reasons.push('STRUCTURED_OUTPUT_REQUIRED');
  }
  const recommendedTier = score >= 60 ? 'frontier' : (score >= 30 ? 'medium' : 'small');
  return { score, recommendedTier, reasons };
}

aideploy-web-assign-day-11:
function calculateRoutingSavings(routingBreakdown: { small: number; medium: number; frontier: number }, avgTokens: number): { blendedCost: number; baselineFrontierCost: number; savingsPercent: number } {
  const totalQueries = routingBreakdown.small + routingBreakdown.medium + routingBreakdown.frontier;
  if (totalQueries <= 0) return { blendedCost: 0, baselineFrontierCost: 0, savingsPercent: 0 };
  const tokensK = avgTokens / 1000;
  const smallCost = routingBreakdown.small * tokensK * 0.0005;
  const medCost = routingBreakdown.medium * tokensK * 0.002;
  const frontCost = routingBreakdown.frontier * tokensK * 0.02;
  const blendedCost = Math.round((smallCost + medCost + frontCost) * 100) / 100;
  const baselineFrontierCost = Math.round((totalQueries * tokensK * 0.02) * 100) / 100;
  const savingsPercent = Math.round((1 - (blendedCost / baselineFrontierCost)) * 100 * 100) / 100;
  return { blendedCost, baselineFrontierCost, savingsPercent };
}

