function resolveProviderFallback<T>(providers: { name: string; invoke: () => { ok: boolean; data?: T; error?: string } }[]): { resolvedProvider: string; result: T; fallbackAttempts: number } {
  let failedAttempts = 0;
  for (const p of providers) {
    try {
      const res = p.invoke();
      if (res.ok && res.data !== undefined) {
        return { resolvedProvider: p.name, result: res.data, fallbackAttempts: failedAttempts };
      }
    } catch {}
    failedAttempts++;
  }
  throw new Error('All providers in fallback chain failed');
}

