class ModelCircuitBreaker {
  private failures: number = 0;
  private state: 'CLOSED' | 'OPEN' | 'HALF_OPEN' = 'CLOSED';
  private openedAtMs: number = 0;
  constructor(public failureThreshold: number, public recoveryTimeoutMs: number) {}
  recordFailure(nowMs: number): void {
    this.failures++;
    if (this.failures >= this.failureThreshold) {
      this.state = 'OPEN';
      this.openedAtMs = nowMs;
    }
  }
  recordSuccess(): void {
    this.failures = 0;
    this.state = 'CLOSED';
    this.openedAtMs = 0;
  }
  getState(nowMs: number): 'CLOSED' | 'OPEN' | 'HALF_OPEN' {
    if (this.state === 'OPEN') {
      if (nowMs - this.openedAtMs >= this.recoveryTimeoutMs) {
        this.state = 'HALF_OPEN';
        return 'HALF_OPEN';
      }
      return 'OPEN';
    }
    return this.state;
  }
}

aideploy-web-exam-day-13:
function calculateLatencyPercentiles(latenciesMs: number[]): { count: number; p50: number; p90: number; p99: number; max: number } {
  if (latenciesMs.length === 0) return { count: 0, p50: 0, p90: 0, p99: 0, max: 0 };
  const sorted = [...latenciesMs].sort((a, b) => a - b);
  const getP = (pct: number) => {
    const idx = Math.min(sorted.length - 1, Math.max(0, Math.ceil((pct / 100) * sorted.length) - 1));
    return sorted[idx];
  };
  return {
    count: sorted.length,
    p50: getP(50),
    p90: getP(90),
    p99: getP(99),
    max: sorted[sorted.length - 1]
  };
}

aideploy-web-assign-day-13:
function evaluateLatencySla(latenciesMs: number[], p95ThresholdMs: number, p99ThresholdMs: number): { p95Actual: number; p99Actual: number; compliant: boolean; breachedPercentile: string | null } {
  if (latenciesMs.length === 0) return { p95Actual: 0, p99Actual: 0, compliant: true, breachedPercentile: null };
  const sorted = [...latenciesMs].sort((a, b) => a - b);
  const getP = (pct: number) => {
    const idx = Math.min(sorted.length - 1, Math.max(0, Math.ceil((pct / 100) * sorted.length) - 1));
    return sorted[idx];
  };
  const p95Actual = getP(95);
  const p99Actual = getP(99);
  if (p95Actual > p95ThresholdMs) {
    return { p95Actual, p99Actual, compliant: false, breachedPercentile: 'P95' };
  }
  if (p99Actual > p99ThresholdMs) {
    return { p95Actual, p99Actual, compliant: false, breachedPercentile: 'P99' };
  }
  return { p95Actual, p99Actual, compliant: true, breachedPercentile: null };
}

