function fixedSizeChunkWithOverlap(text: string, chunkSize: number, overlapSize: number): string[] {
  if (chunkSize <= 0 || overlapSize >= chunkSize) throw new Error('Invalid chunk or overlap size');
  if (text.length === 0) return [];
  if (text.length <= chunkSize) return [text];
  const chunks: string[] = [];
  const step = chunkSize - overlapSize;
  for (let i = 0; i < text.length; i += step) {
    chunks.push(text.slice(i, i + chunkSize));
    if (i + chunkSize >= text.length) break;
  }
  return chunks;
}

aideploy-web-assign-day-16:
function splitMarkdownByHeadings(markdown: string): { heading: string; level: number; content: string }[] {
  const lines = markdown.split('\n');
  const sections: { heading: string; level: number; content: string }[] = [];
  let curHeading = 'root';
  let curLevel = 0;
  let curLines: string[] = [];
  for (const line of lines) {
    const match = line.match(/^(#{1,6})\s+(.*)$/);
    if (match) {
      if (curLines.length > 0 || sections.length > 0 || curHeading !== 'root') {
        sections.push({ heading: curHeading, level: curLevel, content: curLines.join('\n').trim() });
      }
      curHeading = match[2].trim();
      curLevel = match[1].length;
      curLines = [];
    } else {
      curLines.push(line);
    }
  }
  sections.push({ heading: curHeading, level: curLevel, content: curLines.join('\n').trim() });
  return sections.filter(s => s.heading !== 'root' || s.content.length > 0);
}

