function topKCosineSearch(queryVec: number[], candidates: { id: string; vec: number[] }[], k: number): { id: string; score: number }[] {
  const cosine = (a: number[], b: number[]) => {
    let dot = 0, sa = 0, sb = 0;
    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      sa += a[i] * a[i];
      sb += b[i] * b[i];
    }
    if (sa === 0 || sb === 0) return 0;
    return Math.round((dot / (Math.sqrt(sa) * Math.sqrt(sb))) * 10000) / 10000;
  };
  const scored = candidates.map(c => ({ id: c.id, score: cosine(queryVec, c.vec) }));
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, k);
}

