function reciprocalRankFusion(rankedLists: string[][], kConstant: number = 60): { id: string; rrfScore: number }[] {
  const scores = new Map<string, number>();
  for (const list of rankedLists) {
    list.forEach((docId, index) => {
      const rank = index + 1;
      const prev = scores.get(docId) || 0;
      scores.set(docId, prev + (1 / (kConstant + rank)));
    });
  }
  const result = Array.from(scores.entries()).map(([id, raw]) => ({
    id,
    rrfScore: Math.round(raw * 10000) / 10000
  }));
  result.sort((a, b) => b.rrfScore - a.rrfScore);
  return result;
}

