function validateJsonSchemaSimple(obj: any, requiredFields: { key: string; type: 'string' | 'number' | 'boolean' }[]): { valid: boolean; missingFields: string[]; typeMismatches: string[] } {
  if (!obj || typeof obj !== 'object') {
    return { valid: false, missingFields: requiredFields.map(f => f.key), typeMismatches: [] };
  }
  const missingFields: string[] = [];
  const typeMismatches: string[] = [];
  for (const field of requiredFields) {
    if (!(field.key in obj)) {
      missingFields.push(field.key);
    } else if (typeof obj[field.key] !== field.type) {
      typeMismatches.push(field.key);
    }
  }
  return {
    valid: missingFields.length === 0 && typeMismatches.length === 0,
    missingFields,
    typeMismatches
  };
}

