function evaluateExactMatchBenchmark(testCases: { input: string; expected: string }[], candidateFn: (input: string) => string): { totalCases: number; passedCases: number; accuracyPercent: number; failedInputs: string[] } {
  if (testCases.length === 0) return { totalCases: 0, passedCases: 0, accuracyPercent: 0, failedInputs: [] };
  let passed = 0;
  const failed: string[] = [];
  for (const c of testCases) {
    try {
      const actual = candidateFn(c.input);
      if (actual.trim() === c.expected.trim()) {
        passed++;
      } else {
        failed.push(c.input);
      }
    } catch {
      failed.push(c.input);
    }
  }
  const accuracyPercent = Math.round((passed / testCases.length) * 100 * 100) / 100;
  return { totalCases: testCases.length, passedCases: passed, accuracyPercent, failedInputs: failed };
}

aideploy-web-assign-day-21:
function evaluateAssertionRules(outputs: { id: string; text: string }[], rules: { mustContain?: string[]; mustNotContain?: string[]; minLength?: number }): { totalOutputs: number; passingOutputs: number; passRatePercent: number } {
  if (outputs.length === 0) return { totalOutputs: 0, passingOutputs: 0, passRatePercent: 0 };
  let passing = 0;
  for (const out of outputs) {
    let ok = true;
    if (rules.minLength !== undefined && out.text.length < rules.minLength) ok = false;
    if (rules.mustContain) {
      for (const phrase of rules.mustContain) {
        if (!out.text.includes(phrase)) { ok = false; break; }
      }
    }
    if (rules.mustNotContain && ok) {
      for (const phrase of rules.mustNotContain) {
        if (out.text.includes(phrase)) { ok = false; break; }
      }
    }
    if (ok) passing++;
  }
  const passRatePercent = Math.round((passing / outputs.length) * 100 * 100) / 100;
  return { totalOutputs: outputs.length, passingOutputs: passing, passRatePercent };
}

