function calculateRubricWeightedScore(dimensions: { name: string; score: number; weight: number }[]): { weightedTotal: number; maxPossible: number; normalizedPercent: number; passing: boolean } {
  let weightedTotal = 0;
  let maxPossible = 0;
  for (const d of dimensions) {
    weightedTotal += d.score * d.weight;
    maxPossible += 5 * d.weight;
  }
  if (maxPossible <= 0) return { weightedTotal: 0, maxPossible: 0, normalizedPercent: 0, passing: false };
  weightedTotal = Math.round(weightedTotal * 100) / 100;
  maxPossible = Math.round(maxPossible * 100) / 100;
  const normalizedPercent = Math.round((weightedTotal / maxPossible) * 100 * 100) / 100;
  return { weightedTotal, maxPossible, normalizedPercent, passing: normalizedPercent >= 75 };
}

aideploy-web-assign-day-22:
function detectJudgePositionBias(trial1: { firstScore: number; secondScore: number }, trial2Swapped: { firstScore: number; secondScore: number }): { modelAAvg: number; modelBAvg: number; biasDetected: boolean; favoredPosition: 'first' | 'second' | 'none' } {
  const modelAAvg = Math.round(((trial1.firstScore + trial2Swapped.secondScore) / 2) * 100) / 100;
  const modelBAvg = Math.round(((trial1.secondScore + trial2Swapped.firstScore) / 2) * 100) / 100;
  const avgFirst = (trial1.firstScore + trial2Swapped.firstScore) / 2;
  const avgSecond = (trial1.secondScore + trial2Swapped.secondScore) / 2;
  const delta = avgFirst - avgSecond;
  if (delta >= 1.0) {
    return { modelAAvg, modelBAvg, biasDetected: true, favoredPosition: 'first' };
  } else if (delta <= -1.0) {
    return { modelAAvg, modelBAvg, biasDetected: true, favoredPosition: 'second' };
  }
  return { modelAAvg, modelBAvg, biasDetected: false, favoredPosition: 'none' };
}

