function computeExperimentLift(control: { impressions: number; conversions: number }, treatment: { impressions: number; conversions: number }): { controlRatePercent: number; treatmentRatePercent: number; liftPercent: number; winner: 'treatment' | 'control' | 'tied' } {
  const controlRate = control.impressions > 0 ? (control.conversions / control.impressions) * 100 : 0;
  const treatRate = treatment.impressions > 0 ? (treatment.conversions / treatment.impressions) * 100 : 0;
  const controlRatePercent = Math.round(controlRate * 100) / 100;
  const treatmentRatePercent = Math.round(treatRate * 100) / 100;
  let liftPercent = 0;
  if (controlRatePercent > 0) {
    liftPercent = Math.round(((treatmentRatePercent - controlRatePercent) / controlRatePercent) * 100 * 100) / 100;
  }
  let winner: 'treatment' | 'control' | 'tied' = 'tied';
  if (treatmentRatePercent > controlRatePercent) winner = 'treatment';
  else if (controlRatePercent > treatmentRatePercent) winner = 'control';
  return { controlRatePercent, treatmentRatePercent, liftPercent, winner };
}

