aideploy-web-assign-day-25:
function detectQueryCentroidDrift(baselineCentroid: number[], recentQueryVectors: number[][], driftThreshold: number = 0.25): { currentCentroid: number[]; euclideanDrift: number; isDrifted: boolean } {
  if (recentQueryVectors.length === 0 || baselineCentroid.length === 0) {
    return { currentCentroid: [], euclideanDrift: 0, isDrifted: false };
  }
  const dim = baselineCentroid.length;
  const currentCentroid: number[] = new Array(dim).fill(0);
  for (const v of recentQueryVectors) {
    for (let i = 0; i < dim; i++) currentCentroid[i] += v[i];
  }
  for (let i = 0; i < dim; i++) {
    currentCentroid[i] = Math.round((currentCentroid[i] / recentQueryVectors.length) * 10000) / 10000;
  }
  let sumSq = 0;
  for (let i = 0; i < dim; i++) {
    const diff = currentCentroid[i] - baselineCentroid[i];
    sumSq += diff * diff;
  }
  const euclideanDrift = Math.round(Math.sqrt(sumSq) * 10000) / 10000;
  return {
    currentCentroid,
    euclideanDrift,
    isDrifted: euclideanDrift >= driftThreshold
  };
}

