class TraceSpanCollector {
  private active = new Map<string, { name: string; start: number }>();
  private completed: { name: string; durationMs: number }[] = [];
  private counter = 0;
  startSpan(name: string, timestampMs: number): string {
    const id = `span-${++this.counter}`;
    this.active.set(id, { name, start: timestampMs });
    return id;
  }
  endSpan(spanId: string, timestampMs: number): void {
    const span = this.active.get(spanId);
    if (span) {
      this.completed.push({ name: span.name, durationMs: Math.max(0, timestampMs - span.start) });
      this.active.delete(spanId);
    }
  }
  getCompletedSpans(): { name: string; durationMs: number }[] {
    return [...this.completed];
  }
}

