function calculatePipelineBottlenecks(spans: { name: string; durationMs: number }[]): { bottleneckSpan: string; bottleneckDurationMs: number; sharePercent: number; totalDurationMs: number } {
  if (spans.length === 0) return { bottleneckSpan: 'none', bottleneckDurationMs: 0, sharePercent: 0, totalDurationMs: 0 };
  let maxSpan = spans[0];
  let total = 0;
  for (const s of spans) {
    total += s.durationMs;
    if (s.durationMs > maxSpan.durationMs) maxSpan = s;
  }
  const sharePercent = total > 0 ? Math.round((maxSpan.durationMs / total) * 100 * 100) / 100 : 0;
  return {
    bottleneckSpan: maxSpan.name,
    bottleneckDurationMs: maxSpan.durationMs,
    sharePercent,
    totalDurationMs: total
  };
}

