function aggregateUsageByDimension(records: { userId: string; feature: string; model: string; cost: number }[], dimension: 'userId' | 'feature' | 'model'): { key: string; totalCost: number; recordCount: number }[] {
  const map = new Map<string, { totalCost: number; recordCount: number }>();
  for (const r of records) {
    const k = r[dimension];
    const existing = map.get(k) || { totalCost: 0, recordCount: 0 };
    existing.totalCost += r.cost;
    existing.recordCount += 1;
    map.set(k, existing);
  }
  const result = Array.from(map.entries()).map(([key, val]) => ({
    key,
    totalCost: Math.round(val.totalCost * 10000) / 10000,
    recordCount: val.recordCount
  }));
  result.sort((a, b) => b.totalCost - a.totalCost);
  return result;
}

