function detectCostVelocityAnomaly(historicalDailySpend: number[], currentDaySpend: number, anomalyMultiplier: number = 2.0): { isAnomaly: boolean; baselineAvg: number; ratio: number } {
  if (historicalDailySpend.length === 0) return { isAnomaly: false, baselineAvg: 0, ratio: 0 };
  const sum = historicalDailySpend.reduce((a, b) => a + b, 0);
  const baselineAvg = Math.round((sum / historicalDailySpend.length) * 100) / 100;
  const ratio = baselineAvg > 0 ? Math.round((currentDaySpend / baselineAvg) * 100) / 100 : 0;
  const isAnomaly = ratio >= anomalyMultiplier;
  return { isAnomaly, baselineAvg, ratio };
}

