function computeEndpointHealthScore(metrics: { errorRatePercent: number; p99LatencyMs: number; cacheHitRatePercent: number }): { healthScore: number; status: 'HEALTHY' | 'WARNING' | 'CRITICAL' } {
  let score = 100;
  if (metrics.errorRatePercent > 5) score -= 40;
  else if (metrics.errorRatePercent > 1) score -= 20;
  if (metrics.p99LatencyMs > 2000) score -= 30;
  else if (metrics.p99LatencyMs > 1000) score -= 15;
  if (metrics.cacheHitRatePercent < 10) score -= 10;
  score = Math.max(0, Math.min(100, score));
  let status: 'HEALTHY' | 'WARNING' | 'CRITICAL' = 'CRITICAL';
  if (score >= 80) status = 'HEALTHY';
  else if (score >= 50) status = 'WARNING';
  return { healthScore: score, status };
}

