  }
  handleQuery(prompt: string): { status: 'CACHE_HIT' | 'ROUTED_SMALL' | 'ROUTED_FRONTIER' | 'BLOCKED'; output: string } {
    const clean = prompt.trim();
    if (clean.toLowerCase().includes('ignore previous instructions')) {
      return { status: 'BLOCKED', output: 'Request blocked by safety guardrails' };
    }
    if (this.cache.has(clean)) {
      return { status: 'CACHE_HIT', output: this.cache.get(clean)! };
    }
