function auditGatewayOperationalReport(totalQueries: number, cacheHits: number, blockedCount: number, smallCount: number, frontierCount: number): { cacheHitPercent: number; blockPercent: number; estimatedCostUsd: number } {
  if (totalQueries <= 0) return { cacheHitPercent: 0, blockPercent: 0, estimatedCostUsd: 0 };
  const cacheHitPercent = Math.round((cacheHits / totalQueries) * 100 * 100) / 100;
  const blockPercent = Math.round((blockedCount / totalQueries) * 100 * 100) / 100;
  const cost = (smallCount * 0.001) + (frontierCount * 0.02);
  const estimatedCostUsd = Math.round(cost * 100) / 100;
  return { cacheHitPercent, blockPercent, estimatedCostUsd };
}
